local config = {
  str_season_maze_s2_title = "เสียงสะท้อนแห่งฝัน",
  str_season_maze_s2_subtitle = "เสียงสะท้อนแห่งฝัน",
  str_season_maze_s2_even_desc_1001 = "คุณสแกนรอบ ๆ ในความสับสน - ไม่มีศัตรู ไม่มีสมบัติ... ไม่มีอะไรเลย ผนังที่มองไม่เห็นหยุดคุณไว้ในทางของคุณด้วยเสียง \"Thump!\" ที่ดัง\n\n\"กำลังวิเคราะห์สถานการณ์... พลังงานในสามัญชนนี้แกว่งไปมาเกินไปจนไม่สามารถระบุตำแหน่งได้อย่างแม่นยำ\" หน้าของผู้กระจ่างให้สว่างกลายเป็นสีแดงร้อนจากการทำงานที่เร่งรัด \"นี่คือสามัญชนที่ไม่รู้จัก อาจารย์ฟรานซิสกล่าวว่าเขาชอบความไม่แน่นอนของสามัญชนประเภทนี้ นอกจากนี้ ภาพของผู้ฝันที่ยังคงอยู่บางครั้งจะปรากฏขึ้น\"ในคำอื่น ๆ คุณอาจพบเพื่อนเก่าของคุณที่นี่\n\n\"มีเส้นทางการออกเดินทางสามเส้นที่ถูกกำหนดไว้ กรุณาเลือก ข้อสังเกต: เส้นทางที่แตกต่างกันให้รางวัลที่แตกต่างกัน คุณแนะนำให้วางแผนสำหรับสถานการณ์ที่แย่ที่สุดเพื่อหลีกเลี่ยงประสบการณ์การเล่นที่ไม่ดี\"\n\nเหมือนกับการรับรู้ความวิตกกังวลของคุณ ผู้กระจ่างให้สว่างทันทีอธิบายว่า \"ผลที่แย่ที่สุดคือไม่ได้รับรางวัล\" นั่นดีกว่าเยอะแยะ... ใช่ไหม?",
  str_season_maze_s2_even_desc_1002 = "\"กำลังวิเคราะห์สถานการณ์...\" ผู้กระจ่างให้สว่างกำลังมองอยู่ทั่วท้องฟ้า ดูเหมือนว่ามีเพชรใสๆหลายๆอันกำลังเคลื่อนที่อยู่ภายใน... แม้ว่าคุณจะไม่เห็นอะไร แต่คุณรู้ว่าคุณกำลังอยู่ในโลกความฝันที่ไม่รู้จักอีกครั้ง\n\n\"ได้กำหนดเส้นทางการออกเดินทางสามเส้นแล้ว โปรดเลือก\"\n\nเหมือนว่าจะส่งกำลังใจให้คุณ ผู้กระจ่างให้สว่างดึงเสื้อคุณและพูดด้วยเสียงเบาๆ \"ฉันมีความรู้สึกว่าคุณอาจจะจับ Dream Coins ได้ครั้งนี้นะ\"",
  str_season_maze_s2_even_desc_1003 = "\"กำลังวิเคราะห์สถานการณ์...\" อาจเป็นเพราะความตื่นเต้นและความหวาดเสียวจาก \"ความไม่แน่นอน\" ที่คุณรู้สึกในสถานที่ฝันที่ไม่รู้จักก่อนหน้านี้ ทำให้คุณเริ่มรอคอยผลการคำนวณของผู้กระจ่างให้สว่าง\n\n\"สรุป: คุณมีความชอบในสถานที่ฝันที่ไม่รู้จักเหมือนกับอาจารย์ฟรานซิส\"ผู้กระจ่างให้สว่างดูพอใจกับการสรุป \"คำอธิบาย: คุณควรรู้แล้วว่าฉันไม่ได้หลอกคุณ การเล่นเกมในความฝันนั้นน่าสนใจมาก ไม่, ฉันไม่มีความรู้สึกของตัวเอง แต่ฉันสามารถสรุปความรู้สึกของผู้ท่องเที่ยวในฝันได้\"",
  str_season_maze_s2_even_desc_1004 = "ผู้กระจ่างให้สว่างก้มลงและกวาดดินมาห handful  \"อาจารย์ฟรานซิสเคยกล่าวว่ามีสิ่งมีชีวิตที่นุ่มนวลในทะเลที่จะมัดทรายที่ซึมเข้าไปในร่างกายของมันด้วยน้ำตาที่เจ็บปวดจนกระทั่งที่สุดความเจ็บปวดนั้นกลายเป็นมุกที่สวยงาม\"\n\nผู้กระจ่างให้สว่างหยุดพัก, ดูเหมือนเด็กหญิงธรรมดาที่ชอบนิทาน \"มีสิ่งที่คล้ายคลึงกันในฝัน\"",
  str_season_maze_s2_even_desc_1005 = "\"สรุป: ฝันร้ายแตกต่างจากฝันดี\" \n\nแน่นอนว่ามันต่างกัน คุณไม่จำเป็นต้องคิดเลยก็บอกได้ แต่สำหรับผู้กระจ่างให้สว่าง เธอต้องรวบรวมข้อมูลอย่างมากมายเพื่อสรุปความรู้เดียวกัน\n\nนี่คือความหมายของ \"เฉพาะในฝันร้ายเท่านั้นที่ความเจ็บปวดของผู้ฝันจะถูกแปลงเป็น Dream Orb\" หรือเปล่า?!\n\nคุณเริ่มสงสัยว่าผู้กระจ่างให้สว่างรู้จักความหมายของการฝันหรือไม่ และแม้กระทั่งว่าเธอมีฝันหรือไม่เลย",
  str_season_maze_s2_even_desc_1006 = "\"สวัสดีอีกครั้ง\" อิริดอนยืนอยู่หน้าคุณในชุด Justice Knight ที่สมบูรณ์แบบ และถึงแม้ว่าการทักทายของเธอจะบ่งบอกถึงการพบกันที่ไม่คาดคิด แต่ดูเหมือนว่าเธอได้รอคุณมานานแล้ว\n\n\"ไม่มีอะไรสำคัญ ฉันแค่เจอสิ่งดีๆ บางอย่างเมื่อเร็วๆนี้ และกำลังสงสัยว่าคุณจะชอบอะไรบ้าง\" เธอหยุดพูดสักครู่ \"สิทธิ์ในการเลือกนั้นเป็นของคุณเท่านั้น นั่นทำให้มันยุติธรรม\"",
  str_season_maze_s2_even_desc_1007 = "\"เด็กหญิงที่อยู่ข้างหลังคุณ...\" สายตาที่เต็มไปด้วยความสงสัยที่รุนแรงของอิริดอน และคุณสังเกตเห็นมัน\n\n\"ขอโทษที่ทำให้ความรู้สึกของฉันครอบงำฉัน แค่ว่าฉันได้ทำงานกับเรื่องการลักพาตัวมากมายในช่วงนี้...\" เธอลูบหัวผู้กระจ่างให้สว่างอย่างอ่อนโยนก่อนที่จะหันมาหาคุณ \"เธอจะไม่ยอมเดินออกจากข้างคุณแม้แต่ขั้นตอนเดียว น่าจะเห็นคุณเป็นคนที่สำคัญมากสำหรับเธอ\"",
  str_season_maze_s2_even_desc_1008 = "\"ขอบคุณสำหรับความช่วยเหลือของคุณ!\" อิริดอนคืนดาบของเธอเข้าสกอร์แบร์ดและรีบมัดอาชญากรที่นอนอยู่บนพื้น\n\n\"ถ้าคุณไม่ได้ปรากฏขึ้นอย่างกะทันหันและบล็อกทางของเขา ฉันคงต้องไล่ตามเขาข้ามถนนหลายแห่ง\" แม้ว่าคำพูดของเธอ อิริดอนดูไม่เหนื่อยเลย\"ฉันยังมีงานที่ต้องทำอีกมาก และฉันสามารถให้เพียงเหล่านี้เป็นสัญลักษณ์แสดงความขอบคุณ ถ้าคุณไม่รังเกียจ โปรดเลือกดู แล้วฉันจะไปต่อ\"",
  str_season_maze_s2_even_desc_1009 = "\"ช่วงเวลาที่ดี!\" คุณหันไปทางที่เสียงมา และเห็นอิริดอนวิ่งเข้าหาคุณ ผมที่เปียกชุ่มเหงื่อของเธอติดกับแก้มที่แดงอมชมพู\n\n\"ตรงกลางการฝึกฝนของฉันวันนี้ ฉันรู้สึกว่าฉันต้องการคู่ซ้อมอย่างยิ่ง\" คุณแทบจะไม่เคยเห็นอิริดอนมีอารมณ์ที่ร่าเริงและตื่นเต้นเช่นนี้ \"ฉันสามารถสอนคุณเกี่ยวกับจุดอ่อนของคุณ ดังนั้นมาฝึกฝนกับฉันสิ!\"",
  str_season_maze_s2_even_desc_1010 = "\"สำหรับ Knight ของยุติธรรม ร่างกายที่แข็งแรงเพียงอย่างเดียวไม่เพียงพอ\"\n\nหน้าผากของอิริดอนย่นลงด้วยความจริงจัง \"เราต้องสลักกฎหมายลงในหัวใจของเราด้วย แล้วเท่านั้นเราจึงจะสามารถสู้กับความชั่วในชั่วโมงที่สิ้นหวังที่สุดและตัดสินความยุติธรรม\"\n\nอิริดอนจริงๆ ไม่รู้วิธีการผ่อนคลายเลยใช่ไหม?",
  str_season_maze_s2_even_desc_1011 = "อิริดอนจ้องมองลูกประคบสีขาวบริสุทธิ์ในมือของเธออย่างใจจดใจจ่อ แต่เธอก็จับมันแน่นเมื่อเห็นคุณเดินเข้ามา \"เอ่อ... ฉันตั้งใจจะหาที่ที่จะอยู่คนเดียวสักครู่ แต่คุณก็ยังหาฉันเจอ\"\n\n\"โปรดอย่ามองฉันด้วยสายตานั้น ฉันสบายดี ฉันสัญญา\" เธอยิ้มอย่างอายและเปิดฝ่ามือของเธอ \"แค่ว่าลูกประคบสวยๆเหล่านี้ดูเหมือนจะดึงพลังจากความเศร้าของฉัน\"",
  str_season_maze_s2_even_desc_1012 = "\"ดังนั้นคุณเชื่อว่าเหล่าบอลลูกโลกนี้จริง ๆ แล้วมีพลังที่จะปกป้องเราใช่หรือไม่?\" อิริดอนไม่ดูเหมือนจะประหลาดใจหลังจากได้ยินคำอธิบายของคุณ\n\n\"ฉันเห็น... แต่ไม่จำเป็นต้องแลกฉันด้วยสิ่งมีค่าอย่างนี้ ถ้าคุณยืนยันจริง ๆ ฉันคิดว่าฉันสามารถแยกบางส่วนของพวกเขาได้\"",
  str_season_maze_s2_even_desc_1013 = "หัวของคุณร้องเสียงหึหึ และคุณก็เห็นผู้กระจ่างให้สว่างห้า หก เจ็ด แปด เก้าคน...\n\n\"กำลังวิเคราะห์สถานการณ์...\" หน้าของผู้กระจ่างให้สว่างเบลอลง และคุณคิดว่าเสียงของเธอดูวุ่นวายและตื่นตระหนกมากกว่าปกติ \"คำเตือน, นักเดินทางในฝันต้องรักษาความสัมพันธ์ที่เพียงพอกับฝันเพื่อรักษาความเสถียร\"เมื่อคุณตื่นจากสภาวะนั้นแล้วผู้กระจ่างให้สว่างจึงอธิบายจากการทบทวนว่า \"ข้อแจ้ง: ความเสถียรของนักเดินทางในฝันก็มีผลต่อความเสถียรของผู้กระจ่างให้สว่าง หากต้องการหลีกเลี่ยงการทำงานผิดพลาดจากฝั่งของฉัน โปรดรักษาความถี่สอดคล้องกับฝัน\"",
  str_season_maze_s2_even_desc_1014 = "\"คำถาม: คุณต้องการทราบหรือไม่ว่าทำไมอาจารย์ฟรานซิสถึงพัฒนาโมดูลสนับสนุนความฝัน?\"\n\nคุณเหยียบยินยอม และผู้กระจ่างให้สว่างปิดตาเหมือนกำลังพยายามจำ... แม้ว่าสำหรับเธอแล้ว มันเพียงแค่การจัดเรียงข้อมูลที่มีมานานแสนปี\"ตอบ: เคเลสไทต์ที่ถูกเนรเทศได้รับความทุกข์ทรมานจากความบ้าคลั่ง ในการรักษาผู้ที่ป่วย, อาจารย์ฟรานซิสเข้าไปในฝันของพวกเขาในฐานะนักเดินทางในฝัน มันเป็นอันตรายมากสำหรับนักเดินทางที่จะเคลื่อนไหวในฝันและต้องมีเครื่องมือช่วยเพื่อตรวจจับและมอนิเตอร์ความผันผวนของพลังงานอย่างถูกต้อง\"\n\n\"ด้วยความจำเป็นนั้น, อาจารย์ได้พัฒนาโมดูลสนับสนุนฝันสำหรับฉัน\"",
  str_season_maze_s2_even_desc_1015 = "\"ตอบ: อาจารย์ฟรานซิสเชื่อว่าเพียงแค่วิทยาศาสตร์เท่านั้นที่จะช่วยชาวเคเลสไทต์ แต่เขาก็เชื่อว่ามีพลังงานลึกลับอยู่เหนือการสังเกตและความเข้าใจ...\"\n\n\"ไม่, มันไม่ใช่ศาสนาที่คุณรู้จัก พลังงานลึกลับนั้นลึกลับเพราะไม่สามารถสังเกตหรือศึกษาได้ด้วยเทคโนโลยีปัจจุบัน\"เมื่อมีการพูดถึงอาจารย์ฟรานซิส มันเสมอทำให้คุณนึกถึงเวลาที่ผู้กระจ่างให้สว่างทำความสะอาด \"แคชแห่งความเศร้า\" ของอาจารย์\n\nผู้กระจ่างให้สว่างทันทีกลายเป็นความระมัดระวัง \"กำลังวิเคราะห์สถานการณ์... ถ้าคุณต้องการให้ฉันบันทึกแคช คุณสามารถทำได้ผ่านคำสั่งเสียง.\"\n\nสิ่งนั้นทำให้คุณตกใจ... ผู้กระจ่างให้สว่างมีการติดตั้งโมดูลสื่อสารทางจิตใดๆ หรือไม่?",
  str_season_maze_s2_even_desc_1016 = "ผู้กระจ่างให้สว่างต้องการจะพูดอะไรสักอย่างแต่ก็หยุดทันที ดูเหมือนว่าเธอมีคำถาม แต่ไม่สามารถเริ่มต้นการสอบถามได้หากไม่มีคำสั่ง\n\nหลังจากได้รับความยินยอมจากคุณ เธอจึงถามในที่สุด \"คำถาม: ฉันอยากทราบว่า โลกภายนอกนั้นเหมือนกับในฝันหรือไม่?\"\n\nเรื่องราวกลับมาที่ผู้กระจ่างให้สว่างไม่เคยออกจากหอที่เธอ \"เกิด\" คุณบอกเธอว่าโลกภายนอกกว้างขึ้น และสัญญาว่าจะพาเธอไปยังภูเขา ทะเล... ทุกที่ในโลก\"ประกาศ: จนกระทั่งเวลานั้น โปรดเน้นที่จะพัฒนาความสามารถของคุณ\" ผู้กระจ่างให้สว่างเตือนคุณอย่างเข้มงวด แม้ว่าพลุที่ระเบิดในกล่องเล็กๆ ข้างหลังของเธอจะแสดงความรู้สึกที่แท้จริงของเธอ\n\nคุณจริงๆ ได้รู้ตัวแล้วว่า ผู้กระจ่างให้สว่างไม่ใช่แค่เครื่องจักรเท่านั้น มานานแล้ว",
  str_season_maze_s2_even_desc_1017 = "คุณอยากรู้ว่าเธอฝันอะไรไปบ้าง \n\n\"กำลังเรียกข้อมูล...\" เธอปิดตาแล้วเปิดอย่างช้า ๆ \"ขออภัย, คุณไม่ได้รับอนุญาตให้เข้าถึงไฟล์ที่เกี่ยวข้อง\" แต่ถ้าแม้แต่คุณยังไม่ได้รับอนุญาต, ใครในโลกนี้จึงได้รับอนุญาต?\"นี่คือกฎที่ผู้สร้างของฉัน อาจารย์ฟรานซิส กำหนดไว้ ท่านกล่าวว่าเพียงแค่ได้รับประสบการณ์ฝันที่เพียงพอผ่านการท่องเที่ยวในฝันเท่านั้น คนจึงจะสามารถพัฒนาความมั่นคงที่ไม่ยอมแพ้และปัญญาที่ไม่ธรรมดาในการรับมือกับฝันที่ซับซ้อนของ Caelestites โบราณ\"\n\nผู้กระจ่างให้สว่างวางมือลงบนไหล่ของคุณ \"สรุป: ฉันเชื่อว่าคุณจะสามารถเข้าถึงได้ในวันหนึ่ง\"",
  str_season_maze_s2_even_desc_1018 = "\"กำลังค้นหาข้อมูล...\" เธอไม่เคยปิดบังอะไรในการตอบคำถามของคุณเลย แต่ครั้งนี้เธอดูเหมือนจะใช้เวลานานกว่าปกติ\n\n\"ขออภัย, ฐานข้อมูลของฉันไม่มีข้อมูลเกี่ยวกับแหล่งพลังงานของฉัน แต่คุณสามารถมั่นใจได้ว่า จากการประเมินผลการทำงานของฉัน ฉันจะไม่หมดพลังงาน อย่างน้อยไม่ในช่วงที่คุณยังมีชีวิตอยู่\"\n\nคุณไม่แน่ใจว่าควรจะกังวลหรือผ่อนคลาย ด้วยคำตอบที่คลุมเครือนนี้",
  str_season_maze_s2_even_desc_1019 = "คุณได้รับรู้แล้วว่าความฝันนั้นคือสถานที่ที่คุณเคยเข้าไปมาก่อน แต่ตอนนี้มันมีสิ่งที่ดูเหมือนจะเป็นเครื่องมือของ Caelestite และแม้กระทั่งสภาพแวดล้อม\"ตอบ: ในฝัน การสั่นสะเทือนของพลังงานจะแตกต่างกันในแต่ละพื้นที่ เพื่อส่งเสริมการเคลื่อนที่ของ Dream Wayfarer ฉันได้ทำเครื่องหมายในพื้นที่ที่มีการสั่นสะเทือนที่เหมือนกัน แต่เนื่องจากฐานข้อมูลของฉันมีเพียงแบบจำลอง Caelestite ทุกการสั่นสะเทือนจึงถูกแปลและแสดงผลในสไตล์นั้น\"\n\nเธอหยุดพูดสักครู่ก่อนที่จะดำเนินการอย่างระมัดระวังเหมือนว่าเธอทำผิด \"คำถาม: ฉันควรเปลี่ยนการแสดงผลให้คุณหรือไม่?\"\n\nแต่สิ่งนี้ดูเหมาะสมกับคุณมาก\n\nคุณรู้สึกเหมือนอยู่บ้านจริง ๆ อย่างน้อยในที่นี้",
  str_season_maze_s2_even_desc_1020 = "คุณรู้สึกนึกถึงหอยนาutilus ที่อยู่ใน Obelisk of Return แล้วหันมาถามผู้กระจ่างให้สว่างเกี่ยวกับมัน\n\nเธอปิดตา \"กำลังรับข้อมูล...\"\n\nคราวนี้เธอเปิดต eyes อย่างรวดเร็ว \"จากคำอธิบายของคุณ ฉันเดาว่าคุณกำลังพูดถึงหอย โดยทั่วไป Caelestite จะมีหอยหนึ่งหรือหลายเปลือก ปริมาณที่ครอบครองไม่ได้สะท้อนถึงความมั่งคั่งของ Caelestite แต่สายพันธุ์หายากถูกตามหาอย่างมาก แม้จะเกินค่าทางภายในของพวกเขาเป็นสิ่งสะสม ฉันแนะนำคุณให้ลงทุนอย่างรอบคอบ\"แม้กระสุนจะสูญเสียค่าความสำคัญในสายตาของเคเลสไทต์มานานแล้ว แต่คำแนะนำของผู้กระจ่างให้สว่างยังคงมีความเกี่ยวข้องอยู่",
  str_season_maze_s2_even_desc_1021 = "หลังจากที่รู้ว่าไนท์เทียมคือสกุลเงินปัจจุบันของแผ่นดิน ทรงลูกบาศก์ที่อยู่ข้างๆผู้กระจ่างให้สว่างไม่แสดงอาการประหลาดใจเลย \n\nเธอคาดการณ์มันไว้แล้วหรือ?\n\n\"ตอบ: ฉันรู้ว่าสกุลเงินเป็นผลิตภัณฑ์ธรรมชาติของการพัฒนาของสังคม แต่มันไม่มีค่าสำหรับฉัน\"\n\nแล้วค่าความสำคัญสำหรับเธอคืออะไร?หน้าของเธอก็เริ่มแดงอีกครั้ง แต่คุณรู้แล้วว่าเป็นเพราะ \"สมอง\" ของเธอทำงานหนักเกินไป \"ตอบ: ฉันไม่สามารถหาคำตอบของคำถามนี้ได้ แต่จากข้อมูลในอดีต ความสนิทสนมและคำชมจากคุณคือสิ่งที่มีค่าที่สุดสำหรับฉัน\"",
  str_season_maze_s2_even_desc_1022 = "คุณเคยเก็บสิ่งของบางอย่างในฝันที่อาจช่วยคุณสำรวจฝันในอดีต แต่พวกเขาดูเหมือนจะไม่เหมาะสมในฝันนี้...\n\n\"ตอบ: พลังงานสามารถแกว่งไปมาระหว่างฝันได้ แม้ว่าหลักการจะไม่ทราบ แต่การศึกษาแนะนำว่าฝันจริงๆแล้วมีการแลกเปลี่ยนพลังงานตามกฎบางอย่าง สิ่งของเหล่านั้นได้ตามกระแสเข้าสู่ฝันที่แตกต่างกัน คุณสามารถเอาพวกเขาไปได้เพราะพวกเขาไม่ได้เป็นของฝันใดฝันหนึ่ง\"\n\nพวกเขาอาจมาจากที่ไหน?สังเกตว่าคุณยังหลงอยู่ ผู้กระจ่างให้สว่างตอบ \"พวกเขาถูกทิ้งไว้โดยนักเดินทางแห่งฝันที่เข้ามาก่อน\"",
  str_season_maze_s2_even_desc_1023 = "ฉันอยู่ในความฝันมานานแล้ว จะจบเมื่อไหร่นี้?\n\nเธอรู้สึกว่าคุณกำลังเหนื่อย \"คุณสามารถหยุดพักได้ การฟื้นฟูสมดุลของพลังงานในความฝันไม่ใช่งานที่สั้น โดยปกติแล้ว ความฝันมีหลายระดับ ยิ่งคนที่ฝันปิดตัวตนออกจากโลกความจริงมากขึ้น ความฝันก็จะมีระดับมากขึ้น แต่อย่างไรก็ตาม เมื่อพลังงานได้รับการสมดุลใหม่แล้ว การปรับปรุงในชีวิตจริงของพวกเขาก็จะชัดเจนขึ้น\"ผู้กระจ่างให้สว่างเคลื่อนที่ใกล้ขึ้น \"คำอธิบาย: ถ้าคุณรู้สึกเหนื่อย ฉันสามารถชงเครื่องดื่มร้อนให้คุณได้ตลอดเวลา\"",
  str_season_maze_s2_even_desc_1024 = "เมื่อคุณดำดิ่งลึกลงไปในฝัน คุณรู้สึกว่าคุณกำลังเข้าใจกฎเกณฑ์มากขึ้นและมากขึ้น\n\n\"ประกาศ: คุณสามารถใช้ประโยชน์จากกฎและเรียกความทรงจำเกี่ยวกับออโรเรียนที่คุณรู้จักและเรียกพวกเขามาช่วยคุณ แต่โปรดทราบว่าพวกเขาจะไม่เป็นจริง และหลีกเลี่ยงการคิดว่าคุณสามารถทำอะไรก็ได้ในฝัน แม้ว่าด้วยความช่วยเหลือจากฉัน คุณไม่ควรมองข้ามอันตรายที่อาจเกิดขึ้นในฝัน\"คุณจึงสังเกตว่า ผู้กระจ่างให้สว่างพูดด้วยโทนที่แตกต่าง \"สิ่งที่กล่าวไปข้างต้นเป็นการแจ้งเตือนอัตโนมัติที่เปิดใช้งานในบางช่วงโดยโมดูลสนับสนุนความฝัน และไม่ได้สะท้อนถึงการประเมินของผู้กระจ่างให้สว่างต่อคุณ\"",
  str_season_maze_s2_even_desc_1025 = "คุณเห็นเธอยืนหันหลังให้คุณ และลูกบาศก์ที่อยู่ข้างๆ เธอกำลังบันทึกข้อมูลบางอย่าง...\n\n\"คำเตือน, อย่าเข้าใกล้!\"\n\nเมื่อตรวจจับว่ามีใครสักคนกำลังเข้าใกล้ ผู้กระจ่างให้สว่างปล่อยเสียงเตือนที่สูงเสียด้วย แต่ก็รู้ตัวว่ามันคือคุณแล้วจึงปรับระดับเสียงกลับมาเป็นปกติ \"คำอธิบาย: สบายใจได้ ฉันจะประเมินผลการทำงานของคุณอย่างยุติธรรมและให้คะแนนที่เหมาะสม\"คุณสุดท้ายก็รู้สึกตระหนักว่าเธอได้มองดูทุกการเคลื่อนไหวของคุณและให้คะแนนคุณตลอดเวลา!\n\n\"คำอธิบาย: นี่คือคุณสมบัติเพิ่มเติมที่ฉันให้เพื่อให้คุณสามารถตรวจสอบการกระทำของคุณในฝันได้ดียิ่งขึ้น ฉันจะให้รางวัลพิเศษทุกครั้งที่คุณตรงตามเกณฑ์ที่เหมาะสม\"\n\nเอาล่ะ, ไม่สามารถดูถูกเธอได้ เพราะเธอจริงๆ แล้วเป็นครูฝึกที่ยอดเยี่ยมจริงๆ.",
  str_season_maze_s2_even_desc_1026 = "ภายใต้คำแนะนำของเธอ คุณสังเกตเห็นว่ามีจุดเล็ก ๆ ที่สว่างวิบวับลอยอยู่ในอากาศมากมาย \n\n\"คำอธิบาย: พวกเขาคือเหรียญฝัน หน่วยที่เล็กที่สุดที่สร้างขึ้นจากพลังงานฝัน ผ่านกฎของฝัน คุณสามารถแปลงพวกเขาเป็นสิ่งที่คุณต้องการ\"\n\nเห็นว่ามันยังคงเป็นเรื่องที่ยากเกินไปสำหรับคุณ ผู้กระจ่างให้สว่างจึงใช้วิธีอื่น \"พูดง่าย ๆ เหรียญฝันคือสกุลเงินที่นี่ ในขณะที่มันดีกว่าที่จะเก็บเพิ่มเติมเท่าที่คุณสามารถ ฉันไม่แนะนำให้สะสม\"",
  str_season_maze_s2_even_desc_1027 = "\"คำอธิบาย: Dream Devourers ที่เดินทางจะยังคงกินฝันและสร้างถ้ำบนเทือกเขาที่ถูกทำลายลง การกำจัดถ้ำเท่านั้นที่จะสามารถคืนพลังงานให้กลับสู่สมดุล\"\n\nเธอไม่เคยลืมที่จะกล่าวกฎให้คุณฟังซ้ำ ๆ อีกและอีก\n\n\"ฉันแนะนำให้สะสม Dream Coins มากพอก่อนที่จะเผชิญหน้ากับส่วนที่ลึกที่สุดของถ้ำ - Miasma\"",
  str_season_maze_s2_even_desc_1028 = "\"สู้ด้วยความแข็งแกร่งทั้งหมดและเดิมพันทั้งหมดในความเป็นไปได้ที่ไม่น่าจะเป็น หรือใช้ชีวิตที่สงบสุขและมั่นคง\"\n\nอิริดอนมองไปที่ทิศทางไกลขณะที่เธอกัดปากอย่างเล็กน้อย ท่าทางเฉพาะตัวของเธอเมื่อเธอหลงใหลในความคิด\n\n\"ถ้าคุณคิดเกี่ยวกับมัน... ครึ่งแรกของชีวิตของฉันเป็นสิ่งหลังสุด ในขณะที่ครึ่งหลังเป็นสิ่งแรก แม้กระนั้น มันยังคงเป็นชีวิตที่คุ้มค่าในการใช้ชีวิต\"",
  str_season_maze_s2_even_desc_1029 = "\"ทุกสิ่งในโลกนี้มีราคา และความรักของคนที่คุณรักก็ไม่ใช่ข้อยกเว้น\" อิริดอนปิดตาขณะที่เธอพูดด้วยเสียงที่คล้ายกับการยอมรับแต่ก่อนที่คุณจะมีโอกาสพูดอะไร ฉันยกหัวขึ้นและยิ้ม \"เป็นเรื่องน่าเสียดายที่ฉันไม่สามารถตอบรับความรู้สึกของเขาด้วยตัวเอง\" คุณรู้ดีว่าเธอกำลังพูดถึงพ่อของเธอ\n\n\"ฉันจะเป็นผู้พิพากษาสูงสุดที่ยิ่งใหญ่กว่าที่เขาเคยเป็น ฉันแน่ใจ... ว่านั่นจะทำให้เขามีความสุข\"",
  str_season_maze_s2_even_desc_1030 = "\"นี่คือนักโทษที่หนีตัว!\" อิริดอนรวดเร็วที่จะรู้ตัวตนของผู้สัญจร ที่ทันทีหนีออกจากพื้นที่\n\n\"เร็ว! มาแยกกันแล้วมาพบกันที่เป้าหมายที่ปลายของสองถนนนี้!\" เมื่อสังเกตเห็นความกังวลของคุณ อิริดอนเอื้อมมือเข้าไปในกระเป๋าของเธอ \"นี่ สิ่งนี้จะช่วยให้คุณเคลื่อนไหวได้เร็วขึ้น ฉันรู้ว่าทุกอย่างนี้มันเฉียบพลัน... แต่ฉันต้องพึ่งพาคุณ!\"",
